pub fn config(&self, inputs: &[Input]) -> Result<Config> {
    let decorations = self
        .matches
        .get_one::<String>("decorations")
        .map(|s| s.as_str());
    let mut style_components = if decorations == Some("never") {
        StyleComponents(HashSet::new())
    } else if self.matches.get_flag("number") {
        StyleComponents(HashSet::from([StyleComponent::LineNumbers]))
    } else if self.matches.get_count("plain") > 0 {
        StyleComponents(HashSet::from([StyleComponent::Plain]))
    } else if self.matches.contains_id("style") {
        let mut lists = Vec::new();
        if let Some(values) = self.matches.get_many::<String>("style") {
            for value in values {
                lists.push(StyleComponentList::from_str(value)?);
            }
        }
        StyleComponentList::to_components(lists, self.interactive_output, true)
    } else {
        StyleComponents(HashSet::from_iter(
            StyleComponent::Default
                .components(self.interactive_output)
                .into_iter()
                .cloned(),
        ))
    };
    if style_components.grid() && style_components.0.remove(&StyleComponent::Rule) {
        bat_warning!("Style 'rule' is a subset of style 'grid', 'rule' will not be visible.");
    }

    let extra_plain = self.matches.get_count("plain") > 1;
    let no_paging = self.matches.get_flag("no-paging");
    let mut has_stdin = false;
    let mut stdin_is_tty = false;
    for input in inputs {
        if input.is_stdin() {
            has_stdin = true;
            if input.is_interactive_stdin() {
                stdin_is_tty = true;
            }
        }
    }

    let paging_arg = self.matches.get_one::<String>("paging").map(|s| s.as_str());
    let paging_mode = match paging_arg {
        Some("always") => PagingMode::Always,
        Some("never") => PagingMode::Never,
        Some("auto") | None => {
            if extra_plain {
                PagingMode::Never
            } else {
                let allow_auto_pager = !no_paging;
                if !allow_auto_pager {
                    PagingMode::Never
                } else {
                    let stdin_requires_special_paging = has_stdin;
                    if stdin_requires_special_paging {
                        if self.interactive_output {
                            if !stdin_is_tty {
                                PagingMode::QuitIfOneScreen
                            } else {
                                PagingMode::Never
                            }
                        } else {
                            PagingMode::Never
                        }
                    } else if self.interactive_output {
                        PagingMode::QuitIfOneScreen
                    } else {
                        PagingMode::Never
                    }
                }
            }
        }
        _ => unreachable!("other values for --paging are not allowed"),
    };

    let mut syntax_mapping = SyntaxMapping::new();
    syntax_mapping.start_offload_build_all();
    if let Some(values) = self.matches.get_many::<String>("ignored-suffix") {
        for suffix in values {
            syntax_mapping.insert_ignored_suffix(suffix);
        }
    }
    if let Some(values) = self.matches.get_many::<String>("map-syntax") {
        for from_to in values.rev() {
            let parts: Vec<_> = from_to.split(':').collect();
            if parts.len() != 2 {
                return Err("Invalid syntax mapping. The format of the -m/--map-syntax option is '<glob-pattern>:<syntax-name>'. For example: '*.cpp:C++'.".into());
            }
            syntax_mapping.insert(parts[0], MappingTarget::MapTo(parts[1]))?;
        }
    }

    let maybe_term_width = if let Some(w) = self.matches.get_one::<String>("terminal-width") {
        if w.starts_with('+') || w.starts_with('-') {
            if let Ok(delta) = w.parse::<i16>() {
                let old_width: u16 = Term::stdout().size().1;
                let new_width: i32 = i32::from(old_width) + i32::from(delta);
                if new_width <= 0 {
                    Some(old_width as usize)
                } else {
                    Some(new_width as usize)
                }
            } else {
                None
            }
        } else {
            w.parse().ok()
        }
    } else {
        None
    };

    let term_width = maybe_term_width.unwrap_or(Term::stdout().size().1 as usize);
    let tab_width = if style_components.plain() && !paging_mode.uses_pager() {
        0
    } else {
        4
    };

    self.finish_config(
        style_components,
        paging_mode,
        syntax_mapping,
        maybe_term_width.is_some(),
        term_width,
        tab_width,
    )
}

fn finish_config<'a>(
    &'a self,
    style_components: StyleComponents,
    paging_mode: PagingMode,
    syntax_mapping: SyntaxMapping<'a>,
    has_explicit_term_width: bool,
    term_width: usize,
    tab_width: usize,
) -> Result<Config<'a>> {
    let wrapping_mode = if self.interactive_output || has_explicit_term_width {
        if self.matches.get_flag("chop-long-lines") {
            WrappingMode::NoWrapping(true)
        } else {
            match self.matches.get_one::<String>("wrap").map(|s| s.as_str()) {
                Some("character") => WrappingMode::Character,
                Some("never") => WrappingMode::NoWrapping(true),
                Some("auto") | None => {
                    if style_components.plain() {
                        WrappingMode::NoWrapping(false)
                    } else {
                        WrappingMode::Character
                    }
                }
                _ => unreachable!("other values for --wrap are not allowed"),
            }
        }
    } else {
        WrappingMode::NoWrapping(false)
    };

    Ok(Config {
        true_color: is_truecolor_terminal(),
        language: self
            .matches
            .get_one::<String>("language")
            .map(|s| s.as_str())
            .or_else(|| {
                if self.matches.get_flag("show-all") {
                    Some("show-nonprintable")
                } else {
                    None
                }
            }),
        show_nonprintable: self.matches.get_flag("show-all"),
        nonprintable_notation: match self
            .matches
